<?php
require 'config.php'; require_once 'helpers.php';
$check_in=$_GET['check_in']??''; $check_out=$_GET['check_out']??''; $guests=max(0,(int)($_GET['guests']??2));
$sql="SELECT r.*,(SELECT MAX(b.check_out) FROM bookings b WHERE b.room_id=r.id AND b.status!='Cancelled' AND (b.payment_status<>'Unpaid' OR b.expires_at IS NULL OR b.expires_at>NOW()) AND b.check_out>=CURDATE()) next_available,NOT EXISTS(SELECT 1 FROM bookings x WHERE x.room_id=r.id AND x.status!='Cancelled' AND (x.payment_status<>'Unpaid' OR x.expires_at IS NULL OR x.expires_at>NOW()) AND x.check_in<? AND x.check_out>?) selected_available FROM rooms r WHERE r.is_active=1 AND (?=0 OR r.max_guests>=?) ORDER BY r.price DESC";
$roomsStmt=$conn->prepare($sql); $roomsStmt->bind_param('ssii',$check_out,$check_in,$guests,$guests); $roomsStmt->execute(); $rooms=$roomsStmt->get_result();
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Rooms | LORENCE</title><link rel="stylesheet" href="css/style.css"></head><body><header class="nav dark"><a class="logo" href="index.php">LORENCE <span>GRAND HOTEL</span></a><nav class="site-nav"><a data-nav="home" href="index.php">Home</a><a class="active" aria-current="page" data-nav="rooms" href="rooms.php">Rooms</a><a data-nav="amenities" href="index.php#amenities">Amenities</a><a data-nav="experience" href="index.php#experience">Experience</a><a data-nav="contact" href="index.php#contact">Contact</a><a data-nav="track" href="tracking.php">Track booking</a></nav><a class="btn btn-small" href="rooms.php">BOOK NOW</a></header><section class="page-title"><p class="eyebrow">THE COLLECTION</p><h1>Rooms & Suites</h1><p>Choose your private retreat. Availability is shown live for your selected dates.</p></section><main class="room-list"><?php while($room=$rooms->fetch_assoc()): $hasDates=$check_in!==''&&$check_out!==''; $available=!$hasDates||(bool)$room['selected_available']; $gallery=room_images($conn,(int)$room['id']); $suggestedIn=$check_in?:($room['next_available']?:''); $suggestedOut=$check_out?:($room['next_available']?date('Y-m-d',strtotime($room['next_available'].' +1 day')):''); ?><article class="room-wide <?=$available?'':'room-unavailable'?>"><div><div class="room-image" style="background-image:url('<?=h($room['image'])?>')"></div><?php if($gallery):?><div class="room-gallery"><?php foreach($gallery as $image):?><span style="background-image:url('<?=h($image['path'])?>')"></span><?php endforeach;?></div><?php endif;?></div><div class="room-info"><p class="eyebrow"><?=h($room['category'])?></p><h2><?=h($room['name'])?></h2><p><?=h($room['description'])?></p><ul><li>King-size bed</li><li>Complimentary Wi-Fi</li><li>Breakfast included</li><li>24-hour concierge</li></ul><div class="room-bottom"><div><strong><?=peso((float)$room['price'])?> <small>/ night</small></strong><?php if(!$available):?><span class="availability-note">Booked for these dates<?php if($room['next_available']):?> · Available again <?=h(date('F j, Y',strtotime($room['next_available'])))?><?php endif;?></span><?php elseif($room['next_available']):?><span class="availability-note">Next availability after <?=h(date('F j, Y',strtotime($room['next_available'])))?></span><?php endif;?></div><?php if($available):?><a class="btn-reserve" href="booking.php?room_id=<?=$room['id']?>&check_in=<?=urlencode($suggestedIn)?>&check_out=<?=urlencode($suggestedOut)?>&guests=<?=$guests?>">RESERVE <span>→</span></a><?php else:?><span class="btn-reserve btn-disabled">UNAVAILABLE</span><?php endif;?></div></div></article><?php endwhile;?></main><script src="js/spatial.js" defer></script></body></html>
